private RecipeTransferButton(IDrawable icon, IRecipeLayoutDrawable<?> recipeLayout, RecipeTransferService recipeTransferService, Supplier<@Nullable AbstractContainerScreen<?>> parentScreenSupplier, BooleanSupplier maxTransferSupplier, Runnable onSuccessfulTransfer) {
    super(icon, icon);
    this.recipeLayout = recipeLayout;
    this.recipeTransferService = recipeTransferService;
    this.parentScreenSupplier = parentScreenSupplier;
    this.maxTransferSupplier = maxTransferSupplier;
    this.onSuccessfulTransfer = onSuccessfulTransfer;
}

public void update(@Nullable AbstractContainerMenu parentContainer, @Nullable Player player) {
    AbstractContainerScreen<?> parentScreen = parentContainer == null ? null : this.parentScreenSupplier.get();
    this.update(parentScreen, player);
}

@Override
public void tick() {
    Minecraft minecraft = Minecraft.m_91087_();
    this.update(this.parentScreenSupplier.get(), (Player)minecraft.f_91074_);
}

private void update(@Nullable AbstractContainerScreen<?> parentScreen, @Nullable Player player) {
    this.initialized = true;
    this.recipeTransferError = parentScreen != null && player != null ? (IRecipeTransferError)this.recipeTransferService.getTransferRecipeError(parentScreen, this.recipeLayout, player).orElse(null) : RecipeTransferErrorInternal.INSTANCE;
    if (this.recipeTransferError == null || this.recipeTransferError.getType().allowsTransfer) {
        this.button.f_93623_ = true;
        this.button.f_93624_ = true;
    } else {
        this.button.f_93623_ = false;
        IRecipeTransferError.Type type = this.recipeTransferError.getType();
        this.button.f_93624_ = type == IRecipeTransferError.Type.USER_FACING;
    }
}

@Override
protected boolean onMouseClicked(UserInput input) {
    if (!input.isSimulate()) {
        LocalPlayer player = Minecraft.m_91087_().f_91074_;
        AbstractContainerScreen<?> parentScreen = this.parentScreenSupplier.get();
        boolean maxTransfer = this.maxTransferSupplier.getAsBoolean();
        if (parentScreen != null && player != null && this.recipeTransferService.transferRecipe(parentScreen, this.recipeLayout, (Player)player, maxTransfer)) {
            this.onSuccessfulTransfer.run();
        }
    }
    return true;
}

