public class ElementPrefixParser {
    private static final Pattern SPACE_PATTERN = Pattern.compile("\\s");
    private static final Pattern MOD_NAME_SEPARATOR_PATTERN = Pattern.compile("(?=[A-Z_-])|\\s+");
    private final Char2ObjectMap<PrefixInfo<IListElementInfo<?>, IListElement<?>>> map = new Char2ObjectOpenHashMap();
    private final PrefixInfo<IListElementInfo<?>, IListElement<?>> noPrefix;

    public ElementPrefixParser(IIngredientManager ingredientManager, IIngredientFilterConfig config, IColorHelper colorHelper, IModIdHelper modIdHelper, ISearchStorageBuilderFactory searchStorageBuilderFactory) {
        ISearchStorageBuilderFactory limitedStringStorageBuilderFactory = ElementPrefixParser.createLimitedStringStorageBuilderFactory(searchStorageBuilderFactory);
        this.noPrefix = new PrefixInfo("unprefixed", '\u0000', () -> SearchMode.ENABLED, IListElementInfo::getNames, searchStorageBuilderFactory);
        this.addPrefix(new PrefixInfo("mod_names", '@', config::getModNameSearchMode, info -> {
            HashSet<String> modNames = new HashSet<String>(info.getModNames());
            if (config.getSearchModIds()) {
                modNames.addAll(info.getModIds());
            }
            if (config.getSearchModAliases()) {
                for (String modId : info.getModIds()) {
                    modNames.addAll(modIdHelper.getModAliases(modId));
                }
            }
            if (config.getSearchShortModNames()) {
                for (String modName : info.getModNames()) {
                    List<String> shortModNames = ElementPrefixParser.getShortModNames(modName);
                    modNames.addAll(shortModNames);
                }
            }
            HashSet<String> sanitizedModNames = new HashSet<String>();
            for (String modName : modNames) {
                modName = modName.toLowerCase();
                modName = SPACE_PATTERN.matcher(modName).replaceAll("");
                sanitizedModNames.add(modName);
            }
            return sanitizedModNames;
        }, limitedStringStorageBuilderFactory));
        this.addPrefix(new PrefixInfo("tags", '#', config::getTagSearchMode, e -> e.getTagStrings(ingredientManager), limitedStringStorageBuilderFactory));
        this.addPrefix(new PrefixInfo("tooltips", '$', config::getTooltipSearchMode, e -> e.getTooltipStrings(config, ingredientManager), searchStorageBuilderFactory));
        this.addPrefix(new PrefixInfo("creative_tabs", '%', config::getCreativeTabSearchMode, e -> e.getCreativeTabsStrings(ingredientManager), limitedStringStorageBuilderFactory));
        this.addPrefix(new PrefixInfo("colors", '^', config::getColorSearchMode, e -> {
            Iterable<Integer> colors = e.getColors(ingredientManager);
            return StreamSupport.stream(colors.spliterator(), false).map(colorHelper::getClosestColorName).map(Translator::toLowercaseWithLocale).distinct().toList();
        }, limitedStringStorageBuilderFactory));
        this.addPrefix(new PrefixInfo("identifiers", '&', config::getResourceLocationSearchMode, element -> List.of(element.getResourceLocation().toString()), searchStorageBuilderFactory));
    }

